// Files remain in this origin's device storage while the isolated converter runs.
export async function officeJob(action,id,value){
 const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('inkwire-office-printouts',1);r.onupgradeneeded=()=>r.result.createObjectStore('jobs',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Device storage is unavailable. Attach the file instead.'));});
 try{return await new Promise((resolve,reject)=>{const tx=db.transaction('jobs',action==='get'?'readonly':'readwrite'),store=tx.objectStore('jobs');let result;const r=action==='get'?store.get(id):action==='delete'?store.delete(id):store.put({id,...value,updatedAt:Date.now()});r.onsuccess=()=>{result=r.result;};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(Error('Could not save the printout on this device.'));});}finally{db.close();}
}
export async function cleanOfficeJobs(){const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('inkwire-office-printouts',1);r.onupgradeneeded=()=>r.result.createObjectStore('jobs',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=reject;});try{await new Promise((resolve,reject)=>{const tx=db.transaction('jobs','readwrite'),r=tx.objectStore('jobs').openCursor();r.onsuccess=()=>{const cursor=r.result;if(cursor){if(Date.now()-cursor.value.updatedAt>3600000)cursor.delete();cursor.continue();}};tx.oncomplete=resolve;tx.onerror=reject;});}finally{db.close();}}
